Set-StrictMode -Version Latest
$ErrorActionPreference='Stop'
Add-Type -AssemblyName System.Drawing

if([string]::IsNullOrWhiteSpace($ProjectRoot)){$ProjectRoot=[IO.Path]::GetFullPath((Join-Path $PSScriptRoot '..\..'))}else{$ProjectRoot=[IO.Path]::GetFullPath($ProjectRoot)}
function Resolve-In([string]$Path){$p=if([IO.Path]::IsPathRooted($Path)){$Path}else{Join-Path $ProjectRoot $Path};return (Resolve-Path -LiteralPath $p -ErrorAction Stop).Path}
function Resolve-Out([string]$Path){if([IO.Path]::IsPathRooted($Path)){return [IO.Path]::GetFullPath($Path)};return [IO.Path]::GetFullPath((Join-Path $ProjectRoot $Path))}
function C([string]$Hex){return [Drawing.ColorTranslator]::FromHtml($Hex)}
function F([float]$Size,[Drawing.FontStyle]$Style=[Drawing.FontStyle]::Regular){try{return [Drawing.Font]::new('Segoe UI',$Size,$Style,[Drawing.GraphicsUnit]::Pixel)}catch{return [Drawing.Font]::new([Drawing.FontFamily]::GenericSansSerif,$Size,$Style,[Drawing.GraphicsUnit]::Pixel)}}
function Init-G([Drawing.Graphics]$G){$G.SmoothingMode=[Drawing.Drawing2D.SmoothingMode]::AntiAlias;$G.InterpolationMode=[Drawing.Drawing2D.InterpolationMode]::HighQualityBicubic;$G.PixelOffsetMode=[Drawing.Drawing2D.PixelOffsetMode]::HighQuality;$G.CompositingQuality=[Drawing.Drawing2D.CompositingQuality]::HighQuality;$G.TextRenderingHint=[Drawing.Text.TextRenderingHint]::AntiAliasGridFit}
function Draw-Text([Drawing.Graphics]$G,[string]$Text,[Drawing.Font]$Font,[Drawing.Brush]$Brush,[Drawing.RectangleF]$Rect,[Drawing.StringAlignment]$Align=[Drawing.StringAlignment]::Near,[Drawing.StringAlignment]$Line=[Drawing.StringAlignment]::Near){$sf=[Drawing.StringFormat]::new();try{$sf.Alignment=$Align;$sf.LineAlignment=$Line;$sf.Trimming=[Drawing.StringTrimming]::EllipsisCharacter;$G.DrawString($Text,$Font,$Brush,$Rect,$sf)}finally{$sf.Dispose()}}
function Draw-ImageFit([Drawing.Graphics]$G,[Drawing.Image]$Image,[Drawing.RectangleF]$Bounds){$scale=[Math]::Min($Bounds.Width/$Image.Width,$Bounds.Height/$Image.Height);$w=$Image.Width*$scale;$h=$Image.Height*$scale;$x=$Bounds.X+($Bounds.Width-$w)/2;$y=$Bounds.Y+($Bounds.Height-$h)/2;$dest=[Drawing.Rectangle]::new([int][Math]::Round($x),[int][Math]::Round($y),[int][Math]::Round($w),[int][Math]::Round($h));$G.DrawImage($Image,$dest)}
function Draw-Frame([Drawing.Graphics]$G,[Drawing.Image]$Image,[Drawing.Rectangle]$Bounds,[string]$Title,[string]$Subtitle,[Drawing.Color]$Accent,[Drawing.Font]$TitleFont,[Drawing.Font]$SubFont){$panel=[Drawing.SolidBrush]::new((C '#0E1929'));$border=[Drawing.Pen]::new((C '#2A3B51'),3);$accentBrush=[Drawing.SolidBrush]::new($Accent);$white=[Drawing.SolidBrush]::new((C '#F8FAFC'));$muted=[Drawing.SolidBrush]::new((C '#93A4BA'));try{$G.FillRectangle($panel,$Bounds);$G.DrawRectangle($border,$Bounds);$G.FillRectangle($accentBrush,$Bounds.X,$Bounds.Y,8,$Bounds.Height);Draw-Text $G $Title $TitleFont $white ([Drawing.RectangleF]::new($Bounds.X+28,$Bounds.Y+18,$Bounds.Width-55,38));Draw-Text $G $Subtitle $SubFont $muted ([Drawing.RectangleF]::new($Bounds.X+30,$Bounds.Y+59,$Bounds.Width-60,28));Draw-ImageFit $G $Image ([Drawing.RectangleF]::new($Bounds.X+24,$Bounds.Y+105,$Bounds.Width-48,$Bounds.Height-132))}finally{$muted.Dispose();$white.Dispose();$accentBrush.Dispose();$border.Dispose();$panel.Dispose()}}
function Status-Color([string]$Kind){switch($Kind){'pass'{return C '#61E6A5'}'auto'{return C '#35E9B7'}'pending'{return C '#F7B955'}'partial'{return C '#A78BFA'}'conditional'{return C '#F09A78'}default{return C '#FF8EA3'}}}
function Draw-Table([Drawing.Graphics]$G,[Drawing.Rectangle]$Bounds,[string]$Title,[object[]]$Rows,[int]$RowHeight,[Drawing.Color]$Accent,[Drawing.Font]$TitleFont,[Drawing.Font]$HeaderFont,[Drawing.Font]$IdFont,[Drawing.Font]$BodyFont,[Drawing.Font]$StateFont){$panel=[Drawing.SolidBrush]::new((C '#0E1929'));$header=[Drawing.SolidBrush]::new((C '#132238'));$alt=[Drawing.SolidBrush]::new((C '#101D2F'));$white=[Drawing.SolidBrush]::new((C '#F8FAFC'));$muted=[Drawing.SolidBrush]::new((C '#93A4BA'));$accentBrush=[Drawing.SolidBrush]::new($Accent);$border=[Drawing.Pen]::new((C '#2A3B51'),2);$grid=[Drawing.Pen]::new((C '#23354A'),1);try{$G.FillRectangle($panel,$Bounds);$G.DrawRectangle($border,$Bounds);$G.FillRectangle($accentBrush,$Bounds.X,$Bounds.Y,8,$Bounds.Height);Draw-Text $G $Title $TitleFont $white ([Drawing.RectangleF]::new($Bounds.X+28,$Bounds.Y+18,$Bounds.Width-50,42));$hy=$Bounds.Y+72;$G.FillRectangle($header,$Bounds.X+8,$hy,$Bounds.Width-10,46);Draw-Text $G 'ID' $HeaderFont $muted ([Drawing.RectangleF]::new($Bounds.X+28,$hy,180,46)) Near Center;Draw-Text $G 'CHECK' $HeaderFont $muted ([Drawing.RectangleF]::new($Bounds.X+220,$hy,930,46)) Near Center;Draw-Text $G 'STATE' $HeaderFont $muted ([Drawing.RectangleF]::new($Bounds.X+1190,$hy,$Bounds.Width-1210,46)) Near Center;$y=$hy+46;for($i=0;$i-lt$Rows.Count;$i++){$row=$Rows[$i];if(($i%2)-eq1){$G.FillRectangle($alt,$Bounds.X+8,$y,$Bounds.Width-10,$RowHeight)};$G.DrawLine($grid,$Bounds.X+8,$y+$RowHeight,$Bounds.Right-2,$y+$RowHeight);$sb=[Drawing.SolidBrush]::new((Status-Color $row.Kind));try{Draw-Text $G $row.Id $IdFont $white ([Drawing.RectangleF]::new($Bounds.X+28,$y,180,$RowHeight)) Near Center;Draw-Text $G $row.Check $BodyFont $white ([Drawing.RectangleF]::new($Bounds.X+220,$y,930,$RowHeight)) Near Center;Draw-Text $G $row.State $StateFont $sb ([Drawing.RectangleF]::new($Bounds.X+1190,$y,$Bounds.Width-1210,$RowHeight)) Near Center}finally{$sb.Dispose()};$y+=$RowHeight}}finally{$grid.Dispose();$border.Dispose();$accentBrush.Dispose();$muted.Dispose();$white.Dispose();$alt.Dispose();$header.Dispose();$panel.Dispose()}}
function Draw-Badge([Drawing.Graphics]$G,[Drawing.Rectangle]$Bounds,[string]$Label,[string]$Value,[Drawing.Color]$Accent,[Drawing.Font]$LabelFont,[Drawing.Font]$ValueFont){$panel=[Drawing.SolidBrush]::new((C '#132238'));$muted=[Drawing.SolidBrush]::new((C '#93A4BA'));$valueBrush=[Drawing.SolidBrush]::new($Accent);$border=[Drawing.Pen]::new([Drawing.Color]::FromArgb(190,$Accent),2);try{$G.FillRectangle($panel,$Bounds);$G.DrawRectangle($border,$Bounds);Draw-Text $G $Label $LabelFont $muted ([Drawing.RectangleF]::new($Bounds.X+20,$Bounds.Y+10,$Bounds.Width-40,30));Draw-Text $G $Value $ValueFont $valueBrush ([Drawing.RectangleF]::new($Bounds.X+20,$Bounds.Y+42,$Bounds.Width-40,38))}finally{$border.Dispose();$valueBrush.Dispose();$muted.Dispose();$panel.Dispose()}}

