$out=Resolve-Out $OutputPath;if([IO.File]::Exists($out)-and-not$Force){throw "Output exists: $out. Use -Force."};$dir=Split-Path -Parent $out;if(-not[IO.Directory]::Exists($dir)){[IO.Directory]::CreateDirectory($dir)|Out-Null}
